    const records = EXACT_TEST_CHOICE_ORDER_RECORDS.filter(record => GS028_20261002_CASES.some(c => c.id === record.caseId && c.decisionNodes.some(n => n.id === record.nodeId && n.questionVariantId === record.questionVariantId)));
